// ebbinghaus-vocabulary/src/review-modal.ts
var import_obsidian2 = require("obsidian");
var ReviewModal = class extends import_obsidian2.Modal {
  constructor(plugin, queue, onComplete) {
    super(plugin.app);
    /** Session counters */
    this.correctCount = 0;
    this.fuzzyCount = 0;
    this.wrongCount = 0;
    /** Track which words were new (first review) for stats */
    this.newWordCount = 0;
    /** DOM refs for animation targets */
    this.cardInner = null;
    this.plugin = plugin;
    this.queue = queue;
    this.currentIndex = 0;
    this.onComplete = onComplete;
  }
  onOpen() {
    const { contentEl, modalEl } = this;
    modalEl.addClass("ebbing-modal");
    contentEl.addClass("ebbing-modal-content");
    contentEl.empty();
    this.renderCard(contentEl);
    this.contentEl.setAttribute("tabindex", "-1");
    this.contentEl.focus();
  }
  onClose() {
    super.onClose();
    this.cardInner = null;
  }
  // ═══════════════════════════════════════════
  // Rendering
  // ═══════════════════════════════════════════
  /** Render the current card */
  renderCard(parent) {
    parent.empty();
    const word = this.queue[this.currentIndex];
    if (!word) {
      this.renderSummary(parent);
      return;
    }
    this.renderProgress(parent);
    const cardContainer = parent.createDiv("ebbing-card-container");
    const cardInner = cardContainer.createDiv("ebbing-card-inner");
    this.cardInner = cardInner;
    const front = cardInner.createDiv("ebbing-card-front");
    front.createDiv("ebbing-card-word").setText(word.word);
    front.createDiv("ebbing-card-hint").setText("\u70B9\u51FB\u7FFB\u8F6C\u67E5\u770B\u91CA\u4E49");
    front.addEventListener("click", () => {
      this.flipCard(cardInner, word);
    });
    const back = cardInner.createDiv("ebbing-card-back");
    back.createDiv("ebbing-card-word-back").setText(word.word);
    if (word.definition) {
      const defEl = back.createDiv("ebbing-card-section ebbing-card-definition");
      defEl.createDiv("ebbing-card-label").setText("\u91CA\u4E49");
      defEl.createDiv("ebbing-card-value").setText(word.definition);
    }
    if (word.example) {
      const exEl = back.createDiv("ebbing-card-section ebbing-card-example");
      exEl.createDiv("ebbing-card-label").setText("\u4F8B\u53E5");
      exEl.createDiv("ebbing-card-value").setText(word.example);
    }
    if (word.exampleTranslation) {
      const transEl = back.createDiv("ebbing-card-section ebbing-card-translation");
      transEl.createDiv("ebbing-card-label").setText("\u7FFB\u8BD1");
      transEl.createDiv("ebbing-card-value").setText(word.exampleTranslation);
    }
    if (word.construction) {
      const constrEl = back.createDiv("ebbing-card-section ebbing-card-construction");
      constrEl.createDiv("ebbing-card-label").setText("\u6784\u6210");
      constrEl.createDiv("ebbing-card-value").setText(word.construction);
    }
    const buttonsEl = back.createDiv("ebbing-card-buttons");
    this.createFeedbackButton(buttonsEl, "\u274C \u4E0D\u8BA4\u8BC6", "wrong", word);
    this.createFeedbackButton(buttonsEl, "\u{1F914} \u6A21\u7CCA", "fuzzy", word);
    this.createFeedbackButton(buttonsEl, "\u2705 \u8BA4\u8BC6", "correct", word);
    const hintEl = back.createDiv("ebbing-card-keyhint");
    hintEl.setText("\u952E\u76D8: \u7A7A\u683C=\u7FFB\u8F6C  E=\u8BA4\u8BC6  W=\u6A21\u7CCA  Q=\u4E0D\u8BA4\u8BC6");
  }
  /** Create a feedback button with click handler */
  createFeedbackButton(parent, text, result, word) {
    const btn = parent.createEl("button", {
      text,
      cls: `ebbing-feedback-btn ebbing-feedback-${result}`,
      attr: { tabindex: "-1" }
    });
    btn.addEventListener("click", async () => {
      await this.handleFeedback(word, result);
    });
  }
  /** Progress bar and counter */
  renderProgress(parent) {
    const progressEl = parent.createDiv("ebbing-progress");
    const barWrapper = progressEl.createDiv("ebbing-progress-bar-wrapper");
    const bar = barWrapper.createDiv("ebbing-progress-bar");
    const pct = this.currentIndex / this.queue.length * 100;
    bar.style.width = `${pct}%`;
    progressEl.createDiv("ebbing-progress-text").setText(
      `${this.currentIndex + 1} / ${this.queue.length}`
    );
  }
  /** Session completion summary */
  renderSummary(parent) {
    parent.empty();
    const summaryEl = parent.createDiv("ebbing-summary");
    summaryEl.createDiv("ebbing-summary-emoji").setText("\u{1F389}");
    summaryEl.createDiv("ebbing-summary-title").setText("\u590D\u4E60\u5B8C\u6210\uFF01");
    const statsEl = summaryEl.createDiv("ebbing-summary-stats");
    const total = this.correctCount + this.fuzzyCount + this.wrongCount;
    const accuracy = total > 0 ? Math.round(this.correctCount / total * 100) : 0;
    statsEl.createDiv("ebbing-summary-row").setText(
      `\u2705 \u8BA4\u8BC6\uFF1A${this.correctCount}`
    );
    statsEl.createDiv("ebbing-summary-row").setText(
      `\u{1F914} \u6A21\u7CCA\uFF1A${this.fuzzyCount}`
    );
    statsEl.createDiv("ebbing-summary-row").setText(
      `\u274C \u4E0D\u8BA4\u8BC6\uFF1A${this.wrongCount}`
    );
    statsEl.createDiv("ebbing-summary-row ebbing-summary-accuracy").setText(
      `\u6B63\u786E\u7387\uFF1A${accuracy}%`
    );
    const closeBtn = summaryEl.createEl("button", {
      text: "\u5173\u95ED",
      cls: "ebbing-summary-close"
    });
    closeBtn.addEventListener("click", () => {
      this.close();
    });
  }
  // ═══════════════════════════════════════════
  // Interaction
  // ═══════════════════════════════════════════
  /** Flip the card to show the back face */
  flipCard(cardInner, _word) {
    if (cardInner.hasClass("ebbing-flipped"))
      return;
    cardInner.addClass("ebbing-flipped");
  }
  /**
   * Handle a review feedback selection.
   *  1. Apply the review via ReviewEngine
   *  2. Record stats
   *  3. Persist to Canvas
   *  4. Advance to next card (or summary)
   */
  async handleFeedback(word, result) {
    const engine = this.plugin.reviewEngine;
    const oldStage = word.reviewStage;
    const isNew = engine.isNew(word);
    engine.applyReview(word, result);
    this.plugin.dataManager.recordReview(result, isNew);
    switch (result) {
      case "correct":
        this.correctCount++;
        break;
      case "fuzzy":
        this.fuzzyCount++;
        break;
      case "wrong":
        this.wrongCount++;
        break;
    }
    if (isNew)
      this.newWordCount++;
    if (oldStage < 8 && word.reviewStage >= 8) {
    }
    this.plugin.dataManager.updateWord(word);
    await this.plugin.saveData(this.plugin.settings);
    this.currentIndex++;
    if (this.currentIndex >= this.queue.length) {
      this.renderSummary(this.contentEl);
    } else {
      this.renderCard(this.contentEl);
    }
  }
  // ═══════════════════════════════════════════
  // Keyboard Navigation
  // ═══════════════════════════════════════════
  /** Handle keyboard input for efficiency */
  onKeyDown(event) {
    const word = this.queue[this.currentIndex];
    if (!word)
      return;
    if (event.key === " " || event.code === "Space") {
      event.preventDefault();
      event.stopPropagation();
      if (this.cardInner && !this.cardInner.hasClass("ebbing-flipped")) {
        this.flipCard(this.cardInner, word);
      }
      return;
    }
    if (!this.cardInner?.hasClass("ebbing-flipped"))
      return;
    switch (event.key.toLowerCase()) {
      case "e":
        this.handleFeedback(word, "correct");
        event.preventDefault();
        break;
      case "w":
        this.handleFeedback(word, "fuzzy");
        event.preventDefault();
        break;
      case "q":
        this.handleFeedback(word, "wrong");
        event.preventDefault();
        break;
    }
  }
};

