// ebbinghaus-vocabulary/src/review-panel.ts
var ReviewPanel = class extends import_obsidian3.ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    /** Currently selected tab */
    this.activeTab = "due";
    /** Loaded word data (refreshed on each render) */
    this.dueWords = [];
    this.newWords = [];
    this.masteredWords = [];
    this.plugin = plugin;
  }
  getViewType() {
    return VIEW_TYPE_REVIEW;
  }
  getDisplayText() {
    return "Ebbinghaus Vocabulary";
  }
  getIcon() {
    return "book-open";
  }
  async onOpen() {
    await this.refresh();
  }
  // ═══════════════════════════════════════════
  // Refresh Cycle
  // ═══════════════════════════════════════════
  /** Re-read all data from Canvas files and re-render the panel */
  async refresh() {
    const engine = this.plugin.reviewEngine;
    const allWords = await this.plugin.dataManager.loadAllWords();
    this.dueWords = allWords.filter((w) => engine.isDue(w));
    this.newWords = allWords.filter((w) => engine.isNew(w));
    this.masteredWords = allWords.filter((w) => engine.isMastered(w));
    this.render();
  }
  // ═══════════════════════════════════════════
  // Render
  // ═══════════════════════════════════════════
  render() {
    const container = this.containerEl.children[1];
    container.empty();
    container.addClass("ebbing-panel");
    this.renderStats(container);
    this.renderTabs(container);
    this.renderWordList(container);
    this.renderCTA(container);
    this.renderHeatmap(container);
  }
  /** Stats overview bar */
  renderStats(parent) {
    const statsEl = parent.createDiv("ebbing-stats-overview");
    const stats = this.plugin.dataManager.getStats();
    const totalReviewed = Object.values(stats.dailyStats).reduce(
      (sum, d) => sum + d.reviewed,
      0
    );
    const cards = [
      { label: "\u5F85\u590D\u4E60", value: String(this.dueWords.length), cls: "due" },
      { label: "\u65B0\u5B66", value: String(this.newWords.length), cls: "new" },
      { label: "\u5DF2\u638C\u63E1", value: String(this.masteredWords.length), cls: "mastered" },
      { label: "\u603B\u5355\u8BCD", value: String(this.dueWords.length + this.newWords.length + this.masteredWords.length), cls: "total" }
    ];
    for (const card of cards) {
      const cardEl = statsEl.createDiv(`ebbing-stat-card ebbing-stat-${card.cls}`);
      cardEl.createSpan("ebbing-stat-value").setText(card.value);
      cardEl.createSpan("ebbing-stat-label").setText(card.label);
    }
  }
  /** Tab bar for category switching */
  renderTabs(parent) {
    const tabsEl = parent.createDiv("ebbing-tabs");
    const tabs = [
      { id: "due", label: "\u5F85\u590D\u4E60", count: this.dueWords.length },
      { id: "new", label: "\u65B0\u5B66", count: this.newWords.length },
      { id: "mastered", label: "\u5DF2\u638C\u63E1", count: this.masteredWords.length }
    ];
    for (const tab of tabs) {
      const tabEl = tabsEl.createDiv("ebbing-tab");
      if (tab.id === this.activeTab) {
        tabEl.addClass("ebbing-tab-active");
      }
      tabEl.createSpan("ebbing-tab-label").setText(tab.label);
      tabEl.createSpan("ebbing-tab-count").setText(String(tab.count));
      tabEl.addEventListener("click", () => {
        this.activeTab = tab.id;
        this.render();
      });
    }
  }
  /** Scrollable word card list */
  renderWordList(parent) {
    const listEl = parent.createDiv("ebbing-word-list");
    const words = this.getActiveWords();
    if (words.length === 0) {
      const emptyEl = listEl.createDiv("ebbing-empty-state");
      emptyEl.createSpan().setText("\u2728");
      emptyEl.createDiv("ebbing-empty-text").setText(this.getEmptyMessage());
      return;
    }
    for (const word of words) {
      this.renderWordCard(listEl, word);
    }
  }
  /** Single word card in the list */
  renderWordCard(parent, word) {
    const engine = this.plugin.reviewEngine;
    const card = parent.createDiv("ebbing-word-card");
    const left = card.createDiv("ebbing-word-info");
    left.createDiv("ebbing-word-text").setText(word.word);
    const meta = left.createDiv("ebbing-word-meta");
    const stageLabel = engine.getStageLabel(word.reviewStage);
    meta.createSpan("ebbing-word-stage").setText(`Stage ${word.reviewStage} \xB7 ${stageLabel}`);
    const right = card.createDiv("ebbing-word-time");
    if (word.nextReview) {
      const isOverdue = word.nextReview.getTime() < Date.now();
      const timeStr = this.formatRelativeTime(word.nextReview);
      right.createSpan(`ebbing-time ${isOverdue ? "ebbing-overdue" : ""}`).setText(isOverdue ? `\u8FC7\u671F ${timeStr}` : `${timeStr} \u540E`);
    } else if (word.reviewStage >= 8) {
      right.createSpan("ebbing-time ebbing-mastered-check").setText("\u2713");
    } else {
      right.createSpan("ebbing-time").setText("\u65B0\u5355\u8BCD");
    }
    card.addEventListener("click", () => {
      card.toggleClass("ebbing-word-card-expanded", !card.hasClass("ebbing-word-card-expanded"));
      const existing = card.querySelector(".ebbing-word-detail");
      if (card.hasClass("ebbing-word-card-expanded")) {
        if (!existing) {
          const detail = card.createDiv({ cls: "ebbing-word-detail" });
          if (word.definition) {
            detail.createDiv({ cls: "ebbing-detail-row" }).setText(word.definition);
          }
          if (word.example) {
            const exampleRow = detail.createDiv({ cls: "ebbing-detail-row ebbing-detail-example" });
            exampleRow.setText(word.example);
          }
          if (word.exampleTranslation) {
            const transRow = detail.createDiv({ cls: "ebbing-detail-row ebbing-detail-translation" });
            transRow.setText(word.exampleTranslation);
          }
        }
      } else {
        existing?.remove();
      }
    });
  }
  /** CTA button to start reviewing */
  renderCTA(parent) {
    const ctaEl = parent.createDiv("ebbing-cta-wrapper");
    const btn = ctaEl.createEl("button", {
      text: "\u{1F680}  \u5F00\u59CB\u590D\u4E60",
      cls: "ebbing-cta-button"
    });
    btn.addEventListener("click", async () => {
      const { queue } = this.plugin.reviewEngine.buildReviewQueue([
        ...this.dueWords,
        ...this.newWords,
        ...this.masteredWords
      ]);
      if (queue.length === 0) {
        const notice = ctaEl.createDiv("ebbing-notice");
        notice.setText("\u{1F389} \u6682\u65E0\u5F85\u590D\u4E60\u5355\u8BCD\uFF01");
        setTimeout(() => notice.remove(), 3e3);
        return;
      }
      const modal = new ReviewModal(this.plugin, queue, async () => {
        await this.refresh();
        await this.plugin.refreshStatusBar();
      });
      modal.open();
    });
  }
  /** GitHub-style heatmap at the bottom */
  renderHeatmap(parent) {
    const heatmapEl = parent.createDiv("ebbing-heatmap-wrapper");
    heatmapEl.createDiv("ebbing-heatmap-title").setText("\u{1F4C8} \u5B66\u4E60\u70ED\u529B\u56FE");
    const heatmap = new StatsHeatmap(
      heatmapEl,
      this.plugin.dataManager.getStats(),
      this.plugin.settings.heatmapColors
    );
    heatmap.render();
  }
  // ═══════════════════════════════════════════
  // Helpers
  // ═══════════════════════════════════════════
  getActiveWords() {
    switch (this.activeTab) {
      case "due":
        return this.dueWords;
      case "new":
        return this.newWords;
      case "mastered":
        return this.masteredWords;
    }
  }
  getEmptyMessage() {
    switch (this.activeTab) {
      case "due":
        return "\u6CA1\u6709\u5F85\u590D\u4E60\u7684\u5355\u8BCD";
      case "new":
        return "\u6CA1\u6709\u65B0\u5355\u8BCD";
      case "mastered":
        return "\u8FD8\u6CA1\u6709\u5DF2\u638C\u63E1\u7684\u5355\u8BCD";
    }
  }
  /**
   * Format a relative time string for display.
   *
   * @example
   *   "3 小时后" / "2 天前" / "刚刚"
   */
  formatRelativeTime(date) {
    const now = Date.now();
    const diffMs = date.getTime() - now;
    const absMs = Math.abs(diffMs);
    const prefix = diffMs < 0 ? "" : "";
    const suffix = diffMs < 0 ? "\u524D" : "\u540E";
    if (absMs < 6e4)
      return "\u521A\u521A";
    if (absMs < 36e5)
      return `${Math.round(absMs / 6e4)} \u5206\u949F${suffix}`;
    if (absMs < 864e5)
      return `${Math.round(absMs / 36e5)} \u5C0F\u65F6${suffix}`;
    const days = Math.round(absMs / 864e5);
    return `${prefix}${days} \u5929${suffix}`;
  }
};

// ebbinghaus-vocabulary/main.ts
var EbbinghausVocabPlugin = class extends import_obsidian4.Plugin {
  constructor() {
    super(...arguments);
    /** Status bar item showing the daily review count */
    this.statusBarItem = null;
  }
  async onload() {
    await this.loadSettings();
    this.wordParser = new WordParser();
    this.initCoreComponents();
    this.addSettingTab(new EbbinghausSettingTab(this.app, this));
    this.registerView(
      VIEW_TYPE_REVIEW,
      (leaf) => new ReviewPanel(leaf, this)
    );
    this.addRibbonIcon("book-open", "Ebbinghaus Vocabulary", () => {
      this.activateView();
    });
    this.addCommand({
      id: "open-review-panel",
      name: "Open review panel",
      callback: () => this.activateView()
    });
    this.statusBarItem = this.addStatusBarItem();
    this.statusBarItem.addClass("ebbing-status-bar");
    this.statusBarItem.setText("\u{1F4DA} ...");
    this.statusBarItem.addEventListener("click", () => this.activateView());
    this.registerInterval(
      window.setInterval(() => this.refreshStatusBar(), 6e4)
    );
    await this.refreshStatusBar();
  }
  /** Create (or re-create) components that depend on settings */
  initCoreComponents() {
    this.dataManager = new DataManager(this.app.vault, this.settings);
    this.reviewEngine = new ReviewEngine(this.settings);
  }
  /** Open the review panel in the right sidebar */
  async activateView() {
    const { workspace } = this.app;
    const existing = workspace.getLeavesOfType(VIEW_TYPE_REVIEW);
    if (existing.length > 0) {
      workspace.revealLeaf(existing[0]);
      return;
    }
    const leaf = workspace.getRightLeaf(false);
    if (leaf) {
      await leaf.setViewState({
        type: VIEW_TYPE_REVIEW,
        active: true
      });
      workspace.revealLeaf(leaf);
    }
  }
  /** Update the status bar with the current review count */
  async refreshStatusBar() {
    if (!this.statusBarItem)
      return;
    try {
      const allWords = await this.dataManager.loadAllWords();
      const dueCount = allWords.filter(
        (w) => this.reviewEngine.classifyWord(w) === "due"
      ).length;
      if (dueCount > 0) {
        this.statusBarItem.setText(`\u{1F4DA} ${dueCount}`);
        this.statusBarItem.setAttribute("aria-label", `${dueCount} words due for review`);
      } else {
        this.statusBarItem.setText("\u{1F4DA} \u2713");
        this.statusBarItem.setAttribute("aria-label", "No words due");
      }
    } catch {
      this.statusBarItem.setText("\u{1F4DA} !");
    }
  }
  /** Load settings from plugin data, merging with defaults */
  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }
  /** Persist settings to plugin data */
  async saveSettings() {
    await this.saveData(this.settings);
    this.initCoreComponents();
    this.refreshStatusBar();
  }
  onunload() {
  }
};
